## Why This Is Asked
Tests safe CGO buffer management, error propagation via errno, and concurrent invocation patterns.

## Key Concepts
- CGO memory lifetimes across Go/C boundaries
- Preallocated buffers and safe Go->C data transfer
- Handling errno and ERANGE for dynamic resizing
- Concurrency safety with per-call allocations

## Code Example
```javascript
// C header
int format_message(const char* name, char* out, size_t out_size);

// Minimal C impl (header + body)
#include <string.h>
#include <errno.h>
int format_message(const char* name, char* out, size_t out_size){
  const char* greet = "Hello, ";
  size_t needed = strlen(greet) + strlen(name) + 2; // including '!'
  if (out_size <= needed) { errno = ERANGE; return -1; }
  strcpy(out, greet);
  strcat(out, name);
  strcat(out, "!");
  return (int)strlen(out);
}
```

```javascript
// Go binding sketch (conceptual)
package main
/*
#include <stdlib.h>
#include "format.h"
*/
import "C"
import (
  "errors"
  "unsafe"
)

func FormatMessage(name string) (string, error) {
  sizes := []int{128, 256, 512, 1024}
  for _, s := range sizes {
    buf := make([]byte, s)
    cname := C.CString(name)
    defer C.free(unsafe.Pointer(cname))
    n := C.format_message(cname, (*C.char)(unsafe.Pointer(&buf[0])), C.size_t(s))
    if n >= 0 {
      return string(buf[:n]), nil
    }
    if C.errno != C.ERANGE {
      return "", errors.New("format failed")
    }
  }
  return "", errors.New("buffer too small")
}
